function auditActionLabel(value){const parts=String(value||'').split('.'),domain=AUDIT_DOMAIN_LABELS[parts[0]]||AUDIT_OBJECT_LABELS[parts[0]]||parts[0]||'系统',verbKey=parts.slice(1).join('_'),verb=AUDIT_VERB_LABELS[verbKey]||AUDIT_VERB_LABELS[parts.at(-1)]||parts.slice(1).join(' / ')||'操作';return `${domain} · ${verb}`}
