function toast(message,bad=false){const el=$('#toast');el.textContent=message;el.className='toast show'+(bad?' bad':'');setTimeout(()=>el.className='toast',2600)}
async function api(path,options={}){
  const init={credentials:'include',...options};
  if(init.body && !(init.body instanceof FormData) && typeof init.body!=='string'){init.headers={...init.headers,'Content-Type':'application/json'};init.body=JSON.stringify(init.body)}
  let res;
  try{res=await fetch(API+path,init)}catch(err){if(err?.name==='AbortError')throw err;throw new Error('无法连接服务，请稍后重试')}
  let data=null;
  if(res.status!==204){try{data=await res.json()}catch{}}
  if(!res.ok){
    let detail=data?.detail;
    if(typeof detail==='string'&&detail.trim().startsWith('{')){try{const parsed=JSON.parse(detail);if(parsed&&typeof parsed==='object')detail=parsed}catch{}}
    const msg=typeof detail==='string'?detail:(typeof detail?.message==='string'?detail.message:(detail?JSON.stringify(detail):`请求失败 (${res.status})`));
    if(res.status===401 && path!=='/auth/login')showLogin(msg==='请先登录'?'请登录后继续':'登录已失效，请重新登录');
    throw new Error(msg);
  }
  return data;
}
function setPasswordVisible(visible){
  const input=$('#login-password'),button=$('#password-toggle');
  input.type=visible?'text':'password';button.classList.toggle('revealed',visible);button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'隐藏密码':'显示密码');button.title=visible?'隐藏密码':'显示密码';
}
function showLogin(message=''){
  state.user=null;$('#shell').classList.add('hidden');$('#login').classList.remove('hidden');
  $('#login-password').value='';setPasswordVisible(false);$('#login-error').textContent=message;
}
function hasPlatformPermission(required){
  if(!required)return true;const granted=state.user?.permissions||[];
  return granted.some(value=>value==='*'||value===required||(value.endsWith('.*')&&required.startsWith(value.slice(0,-1))));
}
function canView(view){const meta=VIEW_META[view];return Boolean(meta)&&(!meta.adminOnly||state.user?.is_admin)&&hasPlatformPermission(meta.permission)}
