  $$('#nav [data-view]').forEach(x=>x.classList.toggle('hidden',!canView(x.dataset.view)));
  $$('.nav-group').forEach(group=>group.classList.toggle('hidden',!group.querySelector('[data-view]:not(.hidden)')));
