async function go(view,recordHistory=true){
  if(!VIEW_META[view])view='dashboard';
  if(!canView(view))view='dashboard';
  if(state.jobsTimer){clearTimeout(state.jobsTimer);state.jobsTimer=null}
  if(state.mediaTimer){clearTimeout(state.mediaTimer);state.mediaTimer=null}
  if(state.sourcesTimer){clearTimeout(state.sourcesTimer);state.sourcesTimer=null}
  if(state.analysisTimer){clearTimeout(state.analysisTimer);state.analysisTimer=null}
  if(state.curationTimer){clearTimeout(state.curationTimer);state.curationTimer=null}
  if(state.chatTimer){clearInterval(state.chatTimer);state.chatTimer=null}
  if(state.chatDeltaFrame){cancelAnimationFrame(state.chatDeltaFrame);state.chatDeltaFrame=null;state.chatDeltaQueue=null}
  if(state.graph3d){state.graph3d.destroy();state.graph3d=null}
  if(state.chatAbort){state.chatAbort.abort();state.chatAbort=null}
  if(state.retrievalAbort){state.retrievalAbort.abort();state.retrievalAbort=null}
  state.sourceDetailId=null;state.view=view;syncNavigation(view);
  if(recordHistory&&location.hash!==`#${view}`)history.pushState({view},'',`#${view}`);else if(!location.hash)history.replaceState({view},'',`#${view}`);
  const routes={dashboard:renderDashboard,assets:renderAssets,spaces:renderSpaces,documents:renderDocuments,curation:renderCuration,sources:renderSources,search:renderSearch,retrieval:renderRetrievalDebug,integrations:renderIntegrations,knowledge:renderKnowledge,analysis:renderAnalysis,operations:renderOperations,jobs:renderDocumentJobs,models:renderModels,parsers:renderParsers,media:renderMediaPolicies,processing:renderProcessingPolicies,ontologies:renderOntologies,configuration:renderConfiguration,capabilities:renderCapabilities,applications:renderApplicationWorkbench,products:renderKnowledgeSupply,appscenarios:renderCapabilityScenarios,evaluations:renderLaunchTests,appaccess:renderApplicationAccess,feedback:renderRuntimeFeedback,system:renderSystem,orgs:renderOrgs,users:renderUsers,roles:renderRoles,audits:renderAudits};
  try{await routes[view]()}catch(err){page('错误',`<div class="panel empty">${esc(err.message)}</div>`);toast(err.message,true)}
}

async function renderDashboard(){
  actions('<button class="secondary" id="dashboard-source">新建数据源</button><button class="secondary" id="dashboard-space">新建知识空间</button><button class="secondary" id="dashboard-chat">发起问答</button><button id="dashboard-upload">上传文档</button>');
  const [d,spaces,models]=await Promise.all([api('/dashboard'),api('/spaces'),api('/model-configs')]);state.spaces=spaces;const spaceNames=Object.fromEntries(spaces.map(x=>[x.id,x.name]));
  const hasLlm=models.some(x=>x.enabled&&x.model_kind==='llm'),hasEmbedding=models.some(x=>x.enabled&&x.model_kind==='embedding');
  let next={view:'search',label:'开始知识问答',detail:'知识已准备，可通过真实检索和引用验证结果'};
  if(state.user.is_admin&&!spaces.length)next={view:'spaces',label:'创建第一个知识空间',detail:'先确定知识的业务边界和授权范围'};
  else if(state.user.is_admin&&(!hasLlm||!hasEmbedding))next={view:'models',label:'完成模型配置',detail:`${!hasLlm?'大模型未配置':''}${!hasLlm&&!hasEmbedding?' · ':''}${!hasEmbedding?'向量模型未配置':''}`};
  else if(!d.documents&&!d.sources)next={view:'documents',label:'接入第一批真实知识',detail:'上传文件或创建数据源，系统会自动解析和治理'};
  else if(d.running_jobs)next={view:'jobs',label:'查看知识加工进度',detail:`${d.running_jobs} 个任务正在解析、治理或发布`};
  else if(d.failed_jobs)next={view:'jobs',label:'处理异常任务',detail:`${d.failed_jobs} 个任务需要查看原因或重试`};
  const metricData=[['知识空间',d.spaces,'metric-blue'],['文档总量',d.documents,'metric-indigo'],['今日新增',d.documents_today,'metric-cyan'],['正在处理',d.running_jobs,'metric-orange'],['异常任务',d.failed_jobs,'metric-red'],['治理质量',d.quality_score==null?'—':`${d.quality_score}分`,'metric-green']];
  const docs=(d.recent_documents||[]).map(x=>`<button class="activity-row" data-dashboard-doc="${x.id}"><span class="activity-icon document-icon">文</span><span><b>${esc(x.title)}</b><small>${esc(spaceNames[x.space_id]||'未知空间')} · ${fmtDate(x.updated_at)}</small></span><em>${STATUS_LABELS[x.status]||x.status}</em></button>`).join('')||'<div class="compact-empty">暂无文档</div>';
  const jobs=(d.recent_jobs||[]).map(x=>`<button class="activity-row" data-dashboard-job="${x.id}"><span class="activity-icon job-icon">任</span><span><b>${esc(jobTypeLabel(x.job_type))}</b><small>${fmtDate(x.created_at)}${x.error_message?` · ${esc(x.error_message)}`:''}</small></span>${status(x.status)}</button>`).join('')||'<div class="compact-empty">暂无任务</div>';
  const conversations=(d.recent_conversations||[]).map(x=>`<button class="activity-row" data-dashboard-conversation="${x.id}"><span class="activity-icon chat-icon">问</span><span><b>${esc(x.title)}</b><small>${fmtDate(x.updated_at)}</small></span><em>继续</em></button>`).join('')||'<div class="compact-empty">暂无会话</div>';
  page('工作台',`<button class="dashboard-next-step" data-dashboard-next="${next.view}"><span><small>建议下一步</small><b>${esc(next.label)}</b><em>${esc(next.detail)}</em></span><i>前往处理 ›</i></button><div class="dashboard-metrics">${metricData.map(([label,value,kind])=>`<div class="metric ${kind}"><span>${label}</span><b>${value}</b><i></i></div>`).join('')}</div><div class="dashboard-grid"><section class="panel dashboard-panel"><div class="panel-heading"><div><b>最近文档</b><small>最近更新的知识资产</small></div><button class="link-button" data-dashboard-view="documents">查看全部</button></div><div class="activity-list">${docs}</div></section><section class="panel dashboard-panel"><div class="panel-heading"><div><b>任务动态</b><small>解析、同步与知识加工</small></div><button class="link-button" data-dashboard-view="jobs">任务中心</button></div><div class="activity-list">${jobs}</div></section><section class="panel dashboard-panel"><div class="panel-heading"><div><b>数据接入</b><small>${d.sources} 个数据源</small></div><button class="link-button" data-dashboard-view="sources">管理数据源</button></div><div class="health-summary"><div><b>${d.source_status?.success||0}</b><span>同步正常</span></div><div><b>${d.source_status?.failed||0}</b><span>同步失败</span></div><div><b>${d.source_status?.pending||0}</b><span>待同步</span></div><div><b>${d.quality_issues||0}</b><span>质量问题</span></div></div></section><section class="panel dashboard-panel"><div class="panel-heading"><div><b>最近问答</b><small>继续未完成的知识查询</small></div><button class="link-button" data-dashboard-view="search">新建会话</button></div><div class="activity-list">${conversations}</div></section></div>`);
  $('#dashboard-upload').onclick=()=>go('documents').then(()=>$('#doc-upload')?.click());$('#dashboard-source').onclick=()=>go('sources').then(()=>$('#source-add')?.click());$('#dashboard-space').onclick=()=>go('spaces').then(()=>$('#space-add')?.click());$('#dashboard-chat').onclick=()=>go('search').then(()=>$('#conversation-new')?.click());
  $('#content').onclick=e=>{const nextView=e.target.closest('[data-dashboard-next]')?.dataset.dashboardNext;if(nextView)go(nextView);const view=e.target.closest('[data-dashboard-view]')?.dataset.dashboardView;if(view)go(view);const docId=e.target.closest('[data-dashboard-doc]')?.dataset.dashboardDoc;if(docId){const row=(d.recent_documents||[]).find(x=>x.id===docId);if(row)go('documents').then(()=>viewDoc(row))}const jobId=e.target.closest('[data-dashboard-job]')?.dataset.dashboardJob;if(jobId)viewJob(jobId);const conversationId=e.target.closest('[data-dashboard-conversation]')?.dataset.dashboardConversation;if(conversationId)go('search').then(()=>loadConversation(conversationId))};
}

async function renderAssets(){
  actions('<button class="secondary" id="asset-space-add">新建空间</button><button id="asset-upload">上传文档</button>');
  const [spaces,documents,jobs]=await Promise.all([api('/spaces'),api('/documents'),api('/jobs')]);state.spaces=spaces;const names=Object.fromEntries(spaces.map(x=>[x.id,x.name]));const activeJobs=jobs.filter(x=>['queued','running'].includes(x.status));
  page('知识资产',`<div class="summary-strip"><div><span>知识空间</span><b>${spaces.length}</b></div><div><span>文档资产</span><b>${documents.length}</b></div><div><span>处理中</span><b>${activeJobs.length}</b></div><div><span>异常任务</span><b>${jobs.filter(x=>x.status==='failed').length}</b></div></div><div class="asset-grid"><section class="panel"><div class="panel-heading"><div><b>空间与目录</b><small>按业务范围组织和授权知识</small></div><button class="link-button" data-asset-view="spaces">管理空间</button></div>${table(['空间','编码','状态'],spaces.slice(0,8).map(x=>`<tr><td>${esc(x.name)}</td><td class="mono">${esc(x.code)}</td><td>${status(x.enabled?'available':'unavailable')}</td></tr>`))}</section><section class="panel"><div class="panel-heading"><div><b>最近文档</b><small>版本、解析、治理和溯源集中管理</small></div><button class="link-button" data-asset-view="documents">查看全部</button></div>${table(['文档','知识空间','状态','更新时间'],documents.slice(0,8).map(x=>`<tr><td><button class="link-button" data-asset-doc="${x.id}">${esc(x.title)}</button></td><td>${esc(names[x.space_id]||'—')}</td><td>${status(x.status)}</td><td>${fmtDate(x.updated_at)}</td></tr>`))}</section></div>`);
  $('#asset-upload').onclick=()=>go('documents').then(()=>$('#doc-upload')?.click());$('#asset-space-add').onclick=()=>go('spaces').then(()=>$('#space-add')?.click());$('#content').onclick=e=>{const view=e.target.closest('[data-asset-view]')?.dataset.assetView;if(view)go(view);const id=e.target.closest('[data-asset-doc]')?.dataset.assetDoc;if(id){const row=documents.find(x=>x.id===id);if(row)go('documents').then(()=>viewDoc(row))}};
}

async function renderCapabilities(){
  actions('<button id="cap-refresh">重新检测</button>');const d=await api('/capabilities');
  page('能力检测',table(['能力','版本','用途','状态','详情'],d.items.map(x=>`<tr><td>${esc(x.name)}</td><td class="mono">${esc(x.version||'—')}</td><td>${esc(x.required_for)}</td><td>${status(x.available?'available':'unavailable')}</td><td>${esc(x.detail||'—')}</td></tr>`)));
  $('#cap-refresh').onclick=renderCapabilities;
}

async function renderOperations(){
  actions('<button id="operations-refresh">刷新状态</button>');const [jobs,capabilities,spaces]=await Promise.all([api('/jobs'),api('/capabilities'),api('/spaces')]);state.spaces=spaces;
  const conflictsBySpace=await Promise.all(spaces.map(async space=>{try{return (await api(`/knowledge/conflicts?space_id=${space.id}`)).map(row=>({...row,space_name:space.name}))}catch{return []}}));const conflicts=conflictsBySpace.flat();const unavailable=capabilities.items.filter(x=>!x.available);
  const recentJobs=jobs.slice(0,10);page('运营中心',`<div class="summary-strip"><div><span>运行中任务</span><b>${jobs.filter(x=>['queued','running'].includes(x.status)).length}</b></div><div><span>失败任务</span><b>${jobs.filter(x=>x.status==='failed').length}</b></div><div><span>治理冲突</span><b>${conflicts.length}</b></div><div><span>能力异常</span><b>${unavailable.length}</b></div></div><div class="operations-grid"><section class="panel"><div class="panel-heading"><div><b>任务中心</b><small>统一查看解析、同步、索引和 Agent 任务</small></div><button class="link-button" data-operations-view="jobs">查看全部</button></div>${table(['任务','状态','进度','创建时间'],recentJobs.map(x=>`<tr><td><button class="link-button" data-operation-job="${x.id}">${esc(x.target_name||jobTypeLabel(x.job_type))}</button><small class="cell-subtitle">${esc(jobTypeLabel(x.job_type))}</small></td><td>${status(x.status)}</td><td>${progress(x.progress)}</td><td>${fmtDate(x.created_at)}</td></tr>`))}</section><section class="panel"><div class="panel-heading"><div><b>服务能力</b><small>解析与多模态运行依赖</small></div><button class="link-button" data-operations-view="capabilities">能力检测</button></div><div class="capability-list">${capabilities.items.slice(0,10).map(x=>`<div><span class="health-dot ${x.available?'ok':'bad'}"></span><b>${esc(x.name)}</b><small>${esc(x.version||x.detail||'—')}</small></div>`).join('')}</div></section><section class="panel operations-wide"><div class="panel-heading"><div><b>治理异常</b><small>自动治理产生的冲突记录</small></div></div>${table(['知识空间','属性','策略','状态','时间'],conflicts.slice(0,10).map(x=>`<tr><td>${esc(x.space_name)}</td><td>${esc(x.property_name)}</td><td>${esc(x.strategy)}</td><td>${status(x.status)}</td><td>${fmtDate(x.created_at)}</td></tr>`))}</section></div>`);
  $('#operations-refresh').onclick=renderOperations;$('#content').onclick=e=>{const view=e.target.closest('[data-operations-view]')?.dataset.operationsView;if(view)go(view);const id=e.target.closest('[data-operation-job]')?.dataset.operationJob;if(id)viewJob(id)};
}

async function renderConfiguration(){
  if(!state.user.is_admin)return go('dashboard');actions();const [models,parsers,mediaPolicies,chunks,extracts,governs,ontologies]=await Promise.all([api('/model-configs'),api('/parser-policies'),api('/media-policies'),api('/chunk-policies'),api('/extraction-policies'),api('/governance-policies'),api('/ontologies')]);
  const categories=[
    {view:'models',icon:'模',title:'模型服务',description:'大模型、向量、重排、视觉和语音模型',count:models.length,detail:`${models.filter(x=>x.enabled).length} 个启用 · ${models.filter(x=>x.is_default).length} 个默认`},
    {view:'parsers',icon:'解',title:'解析策略',description:'原生、Docling、OCR和表格图片提取',count:parsers.length,detail:`${parsers.filter(x=>x.enabled).length} 个启用 · ${parsers.filter(x=>x.is_default).length} 个默认`},
    {view:'media',icon:'媒',title:'媒体策略',description:'音视频转写、视频抽帧、OCR与视觉理解',count:mediaPolicies.length,detail:`${mediaPolicies.filter(x=>x.enabled).length} 个启用 · ${mediaPolicies.filter(x=>x.is_default).length} 个默认`},
    {view:'processing',icon:'加',title:'加工策略',description:'切片、语义抽取和自动治理策略',count:chunks.length+extracts.length+governs.length,detail:`切片 ${chunks.length} · 抽取 ${extracts.length} · 治理 ${governs.length}`},
    {view:'ontologies',icon:'构',title:'知识结构',description:'本体、词表、实体类型与关系类型',count:ontologies.length,detail:`${ontologies.filter(x=>x.enabled).length} 个启用`},
  ];
  const modelKinds=['llm','embedding','reranker','vision','asr'];page('配置中心',`<div class="configuration-hero"><div><b>平台能力配置</b><span>集中管理模型、解析、加工与知识结构</span></div><div class="configuration-health">${modelKinds.map(kind=>{const configured=models.some(x=>x.model_kind===kind&&x.enabled);return `<span class="${configured?'configured':'missing'}">${kind.toUpperCase()} · ${configured?'已配置':'未配置'}</span>`}).join('')}</div></div><div class="configuration-grid">${categories.map(x=>`<button class="configuration-card" data-config-view="${x.view}"><span class="configuration-icon">${x.icon}</span><span class="configuration-copy"><b>${x.title}</b><small>${x.description}</small><em>${x.detail}</em></span><strong>${x.count}</strong><i>›</i></button>`).join('')}</div><section class="panel config-status-panel"><div class="panel-heading"><div><b>模型运行状态</b><small>连接测试结果来自真实模型配置</small></div><button class="link-button" data-config-view="models">管理模型</button></div>${table(['名称','类型','供应商','默认','连接状态'],models.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.model_kind)}</td><td>${esc(x.provider)}</td><td>${x.is_default?'是':'—'}</td><td>${status(x.last_test_status||'not_tested')}</td></tr>`))}</section>`);$('#content').onclick=e=>{const view=e.target.closest('[data-config-view]')?.dataset.configView;if(view)go(view)};
}

async function renderSystem(){
  if(!state.user.is_admin)return go('dashboard');actions();const [orgs,users,roles,audits]=await Promise.all([api('/org-units'),api('/users'),api('/roles'),api('/audit-events')]);
  const cards=[['orgs','组','组织机构',orgs.length,'维护集团、子企业和部门层级'],['users','用','用户管理',users.length,'管理账号、组织归属和启停状态'],['roles','权','角色权限',roles.length,'管理角色和知识访问权限'],['audits','审','审计日志',audits.length,'追踪平台操作和配置变更']];
  page('系统管理',`<div class="system-grid">${cards.map(([view,icon,title,count,desc])=>`<button class="system-card" data-system-view="${view}"><span>${icon}</span><b>${title}</b><strong>${count}</strong><small>${desc}</small><i>进入管理 ›</i></button>`).join('')}</div><section class="panel"><div class="panel-heading"><div><b>最近审计</b><small>最近发生的平台管理操作</small></div><button class="link-button" data-system-view="audits">查看全部</button></div>${table(['时间','业务操作','业务对象','操作者'],audits.slice(0,10).map(x=>`<tr><td>${fmtDate(x.created_at)}</td><td>${esc(auditActionLabel(x.action))}</td><td>${esc(auditObjectLabel(x.object_type))}</td><td>${esc(auditActorLabel(x.actor_id,users))}</td></tr>`))}</section>`);$('#content').onclick=e=>{const view=e.target.closest('[data-system-view]')?.dataset.systemView;if(view)go(view)};
}

async function renderModels(){
  actions(state.user.is_admin?'<button id="model-add">新增模型</button>':'');const rows=await api('/model-configs');
  page('模型配置',table(['名称','类型','供应商','模型','凭据 / 运行方式','默认','测试','操作'],rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.model_kind)}</td><td>${esc(x.provider)}</td><td class="mono">${esc(x.model_name)}</td><td>${esc(x.api_key_status)}</td><td>${x.is_default?'是':'—'}</td><td>${status(x.last_test_status)}${x.last_test_message?`<small class="table-note">${esc(x.last_test_message)}</small>`:''}</td><td class="actions">${btn('测试','model-test',x.id)}${state.user.is_admin?btn('编辑','model-edit',x.id)+btn('删除','model-delete',x.id,'danger'):''}</td></tr>`)));
  if(state.user.is_admin)$('#model-add').onclick=()=>editModel(); bindModel(rows);
}
function modelForm(x={}){const c=x.config||{},custom=Object.fromEntries(Object.entries(c).filter(([key])=>!['timeout','retry','max_retries','concurrency','temperature','max_tokens'].includes(key)));return field('name','名称',x.name,'text','required')+`<div class="field-row">${selectField('model_kind','模型类型',[['llm','大模型'],['embedding','向量模型'],['reranker','重排模型'],['vision','视觉模型'],['asr','语音模型']],x.model_kind||'llm')}${selectField('provider','供应商',[['kimi','Kimi'],['openai','OpenAI'],['openai_compatible','OpenAI 兼容'],['groq','Groq'],['litellm','LiteLLM'],['huggingface','HuggingFace'],['bge','BGE'],['fastembed','FastEmbed']],x.provider||'kimi')}</div>`+field('model_name','模型标识',x.model_name,'text','required')+field('base_url','API 地址',x.base_url||'')+field('api_key','API Key','','password',x.id?'placeholder="留空保持不变"':'')+`<div class="field-row">${field('timeout','超时（秒）',c.timeout??60,'number','required min="1" max="3600"')}${field('retry','重试次数',c.retry??c.max_retries??2,'number','required min="0" max="10"')}</div><div class="field-row">${field('concurrency','并发数',c.concurrency??4,'number','required min="1" max="100"')}${field('temperature','温度',c.temperature??0.2,'number','required min="0" max="2" step="0.01"')}${field('max_tokens','最大 Token',c.max_tokens??4096,'number','required min="1" max="200000"')}</div>`+area('custom_config','自定义参数',custom,true)+`<div class="field-row">${check('enabled','启用',x.enabled??true)}${check('is_default','设为默认',x.is_default||false)}</div>`}
async function editModel(x){const ok=await modal(x?'编辑模型':'新增模型',modelForm(x),async d=>{d.config={...(d.custom_config||{}),timeout:Number(d.timeout),retry:Number(d.retry),concurrency:Number(d.concurrency),temperature:Number(d.temperature),max_tokens:Number(d.max_tokens)};['custom_config','timeout','retry','concurrency','temperature','max_tokens'].forEach(key=>delete d[key]);if(!d.api_key)delete d.api_key;await api(x?`/model-configs/${x.id}`:'/model-configs',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderModels()}}
function bindModel(rows){$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);try{if(b.dataset.action==='model-test'){toast('正在检测');const r=await api(`/model-configs/${x.id}/test`,{method:'POST'});toast(r.message,r.status!=='success');renderModels()}if(b.dataset.action==='model-edit')editModel(x);if(b.dataset.action==='model-delete'&&confirm(`删除 ${x.name}？`)){await api(`/model-configs/${x.id}`,{method:'DELETE'});renderModels()}}catch(err){toast(err.message,true)}}}

async function renderParsers(){
  actions(state.user.is_admin?'<button id="parser-add">新增策略</button>':'');const rows=await api('/parser-policies');state.policies=rows;
  page('解析策略',table(['名称','解析器','OCR','语言','表格','默认','状态','操作'],rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.parser_type)}</td><td>${x.enable_ocr?'开':'关'}</td><td class="mono">${esc(x.ocr_language)}</td><td>${x.extract_tables?'是':'否'}</td><td>${x.is_default?'是':'—'}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${state.user.is_admin?btn('编辑','parser-edit',x.id)+btn('删除','parser-delete',x.id,'danger'):''}</td></tr>`)));
  if(state.user.is_admin)$('#parser-add').onclick=()=>editParser();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);if(b.dataset.action==='parser-edit')editParser(x);if(b.dataset.action==='parser-delete'&&confirm(`删除 ${x.name}？`)){try{await api(`/parser-policies/${x.id}`,{method:'DELETE'});renderParsers()}catch(err){toast(err.message,true)}}};
}
function parserForm(x={}){return field('name','名称',x.name,'text','required')+`<div class="field-row">${selectField('parser_type','解析器',[['auto','自动'],['native','原生'],['docling','Docling']],x.parser_type||'auto')}${field('ocr_language','OCR 语言',x.ocr_language||'chi_sim+eng')}</div>`+`<div class="field-row">${field('max_pages','最大页数',x.max_pages||'','number','min="1"')}${area('config','附加参数',x.config||{},true)}</div>`+`<div class="field-row">${check('enable_ocr','启用 OCR',x.enable_ocr??true)}${check('extract_tables','提取表格',x.extract_tables??true)}${check('extract_images','提取图片',x.extract_images||false)}${check('enabled','启用',x.enabled??true)}${check('is_default','设为默认',x.is_default||false)}</div>`}
async function editParser(x){const ok=await modal(x?'编辑策略':'新增策略',parserForm(x),async d=>{d.max_pages=d.max_pages?Number(d.max_pages):null;await api(x?`/parser-policies/${x.id}`:'/parser-policies',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderParsers()}}

function mediaTypeChecks(selected=['image','audio','video']){return `<fieldset class="media-choice"><legend>适用媒介</legend>${[['image','图片'],['audio','音频'],['video','视频']].map(([value,label])=>`<label class="check"><input type="checkbox" name="media_${value}" ${selected.includes(value)?'checked':''}>${label}</label>`).join('')}</fieldset>`}
function mediaPolicyForm(x={}){
  const c=x.config||{},f=c.frame||{},o=c.ocr||{},a=c.asr||{},v=c.vision||{},video=c.video||{};
  const asrModels=(state.models||[]).filter(row=>row.model_kind==='asr'),visionModels=(state.models||[]).filter(row=>row.model_kind==='vision');
  return field('name','策略名称',x.name||'','text','required maxlength="200"')+area('description','说明',x.description||'')+mediaTypeChecks(x.applicable_media_types||['image','audio','video'])+
    `<div class="field-row">${selectField('processing_mode','处理方式',[['hybrid','混合处理'],['local','仅本地'],['cloud','云端处理']],c.processing_mode||'hybrid')}${selectField('frame_mode','视频抽帧方式',[['smart','智能抽帧'],['fixed_interval','固定间隔'],['fixed_fps','固定帧率'],['scene','场景变化']],f.mode||'smart')}</div>`+
    `<fieldset><legend>任务限制</legend><div class="field-row">${field('max_duration_seconds','最大时长（秒）',c.max_duration_seconds??14400,'number','required min="1" max="86400"')}${field('max_file_size_mb','最大文件（MB）',Math.round((c.max_file_size_bytes??2147483648)/1048576),'number','required min="1" max="20480"')}</div><div class="field-row">${field('task_timeout_seconds','任务超时（秒）',c.task_timeout_seconds??14400,'number','required min="30" max="86400"')}${field('temporary_file_ttl_seconds','临时文件保留（秒）',c.temporary_file_ttl_seconds??3600,'number','required min="0" max="86400"')}</div><div class="field-row">${field('max_retries','最大重试',c.max_retries??2,'number','required min="0" max="10"')}${field('concurrency','任务并发',c.concurrency??1,'number','required min="1" max="16"')}</div><div class="field-row">${selectField('cloud_confirmation_mode','云处理确认',[['per_upload','每次上传确认'],['always_allow','始终允许'],['disabled','禁止云处理']],c.cloud_confirmation_mode||'per_upload')}${selectField('failure_mode','失败处理',[['partial','保留已成功结果'],['fail','整体失败']],c.failure_mode||'partial')}</div></fieldset>`+
    `<fieldset><legend>视频与关键帧</legend><div class="field-row">${field('frame_start_seconds','开始时间（秒）',f.start_seconds??0,'number','required min="0" max="86400" step="0.1"')}${field('frame_end_seconds','结束时间（秒）',f.end_seconds??'','number','min="0" max="86400" step="0.1"')}</div>`+
    `<div class="field-row">${field('interval_seconds','抽帧间隔（秒）',f.interval_seconds??30,'number','required min="0.5" max="600" step="0.5"')}${field('fps','抽帧帧率（帧/秒）',f.fps??0.1,'number','required min="0.01" max="2" step="0.01"')}</div>`+
    `<div class="field-row">${field('minimum_interval_seconds','最小抽帧间隔（秒）',f.minimum_interval_seconds??0.5,'number','required min="0.1" max="600" step="0.1"')}${field('maximum_interval_seconds','最大抽帧间隔（秒）',f.maximum_interval_seconds??45,'number','required min="0.5" max="3600" step="0.5"')}</div>`+
    `<div class="field-row">${field('scene_threshold','场景阈值',f.scene_threshold??0.32,'number','required min="0.01" max="0.99" step="0.01"')}${field('frames_per_scene','每场景关键帧',f.frames_per_scene??1,'number','required min="1" max="3"')}</div>`+
    `<div class="field-row">${field('minimum_scene_seconds','最短场景（秒）',f.minimum_scene_seconds??1,'number','required min="0" max="600" step="0.5"')}${field('maximum_scene_seconds','最长场景（秒）',f.maximum_scene_seconds??600,'number','required min="1" max="3600" step="1"')}</div>`+
    `<div class="field-row">${field('max_frames','最大抽帧数',f.max_frames??120,'number','required min="1" max="10000"')}${field('max_image_edge','关键帧最长边',f.max_image_edge??1280,'number','required min="256" max="4096"')}</div>`+
    `<div class="field-row">${field('jpeg_quality','JPEG 质量',f.jpeg_quality??90,'number','required min="40" max="100"')}${field('perceptual_hash_distance','去重阈值',f.perceptual_hash_distance??5,'number','required min="0" max="64"')}</div>`+
    `<div class="field-row">${check('extract_audio_track','提取视频音轨',video.extract_audio_track??true)}${check('scene_detection_enabled','场景检测',video.scene_detection_enabled??true)}${check('perceptual_hash_enabled','关键帧去重',f.perceptual_hash_enabled??true)}${check('include_first','保留首帧',f.include_first??true)}${check('include_last','保留尾帧',f.include_last??true)}</div></fieldset>`+
    `<fieldset><legend>语音识别</legend>`+
    `<div class="field-row">${selectField('asr_model_config_id','语音识别模型',opt(asrModels,'未配置'),a.model_config_id||'')}${selectField('vision_model_config_id','视觉模型',opt(visionModels,'未配置'),v.model_config_id||'')}</div>`+
    `<div class="field-row">${field('asr_language','转写语言',a.language||'zh')}${field('maximum_segment_seconds','VAD 分段（秒）',a.maximum_segment_seconds??30,'number','required min="1" max="600"')}</div><div class="field-row">${field('segment_overlap_seconds','分段重叠（秒）',a.segment_overlap_seconds??0.5,'number','required min="0" max="10" step="0.1"')}${field('minimum_speech_seconds','最短语音（秒）',a.minimum_speech_seconds??0.2,'number','required min="0" max="30" step="0.1"')}</div>`+
    `<div class="field-row">${selectField('silence_policy','静音处理',[['metadata_only','仅保留元数据'],['empty_transcript','保留空转写'],['fail','任务失败']],a.silence_policy||'metadata_only')}${check('enable_asr','启用 ASR',a.enabled??true)}${check('video_asr_enabled','视频执行 ASR',video.asr_enabled??true)}</div><div class="field-row">${check('auto_detect_language','自动识别语言',a.auto_detect_language??true)}${check('vad','启用 VAD',a.vad??true)}${check('punctuation','恢复标点',a.punctuation??true)}${check('speaker_diarization','区分说话人',a.speaker_diarization??false)}</div><div class="field-row">${check('extract_audio_events','提取音频事件',a.extract_audio_events??true)}${check('generate_summary','生成整体摘要',a.generate_summary??true)}${check('generate_chapters','生成章节',a.generate_chapters??true)}</div></fieldset>`+
    `<fieldset><legend>OCR 与视觉</legend><div class="field-row">${field('ocr_language','OCR 语言',o.language||'chi_sim+eng')}${field('ocr_minimum_confidence','OCR 最低置信度',o.minimum_confidence??35,'number','required min="0" max="100" step="1"')}</div><div class="field-row">${selectField('vision_execution','视觉运行位置',[['cloud','云端模型'],['local','本地模型']],v.execution||'cloud')}${field('vision_max_tokens','视觉最大 Token',v.max_tokens??2048,'number','required min="64" max="4000"')}</div><div class="field-row">${field('vision_batch_size','每次图片数',v.batch_size??1,'number','required min="1" max="20"')}${field('vision_concurrency','视觉并发',v.concurrency??1,'number','required min="1" max="8"')}</div><div class="field-row">${field('vision_timeout_seconds','视觉超时（秒）',v.timeout_seconds??120,'number','required min="5" max="900"')}${field('vision_prompt_version','Prompt 版本',v.prompt_version||'media-visible-facts-v1')}</div><div class="field-row">${check('enable_ocr','启用 OCR',o.enabled??true)}${check('enable_vision','启用视觉理解',v.enabled??true)}${check('generate_scene_summary','生成场景摘要',v.generate_scene_summary??true)}${check('generate_video_summary','生成视频摘要',v.generate_video_summary??true)}</div></fieldset>`+
    `<div class="field-row">${check('cloud_processing_allowed','允许云处理',c.cloud_processing_allowed??true)}${check('enabled','启用',x.enabled??true)}${check('is_default','设为默认',x.is_default||false)}</div>`;
}
function mediaPolicyPayload(d,form,existing={}){
  const types=['image','audio','video'].filter(type=>d[`media_${type}`]);if(!types.length)throw new Error('至少选择一种适用媒介');
  const scenePositions={1:['middle'],2:['start','end'],3:['start','middle','end']}[Number(d.frames_per_scene)]||['middle'];
  const config={...existing,processing_mode:d.processing_mode,cloud_processing_allowed:Boolean(d.cloud_processing_allowed),cloud_confirmation_mode:d.cloud_confirmation_mode,max_duration_seconds:Number(d.max_duration_seconds),max_file_size_bytes:Number(d.max_file_size_mb)*1048576,task_timeout_seconds:Number(d.task_timeout_seconds),max_retries:Number(d.max_retries),concurrency:Number(d.concurrency),temporary_file_ttl_seconds:Number(d.temporary_file_ttl_seconds),failure_mode:d.failure_mode,video:{...(existing.video||{}),extract_audio_track:Boolean(d.extract_audio_track),asr_enabled:Boolean(d.video_asr_enabled),scene_detection_enabled:Boolean(d.scene_detection_enabled)},frame:{...(existing.frame||{}),mode:d.frame_mode,start_seconds:Number(d.frame_start_seconds),end_seconds:d.frame_end_seconds===''?null:Number(d.frame_end_seconds),interval_seconds:Number(d.interval_seconds),minimum_interval_seconds:Number(d.minimum_interval_seconds),maximum_interval_seconds:Number(d.maximum_interval_seconds),fps:Number(d.fps),scene_threshold:Number(d.scene_threshold),minimum_scene_seconds:Number(d.minimum_scene_seconds),maximum_scene_seconds:Number(d.maximum_scene_seconds),scene_positions:scenePositions,frames_per_scene:Number(d.frames_per_scene),smart_max_interval_seconds:Number(d.maximum_interval_seconds),include_first:Boolean(d.include_first),include_last:Boolean(d.include_last),max_frames:Number(d.max_frames),max_image_edge:Number(d.max_image_edge),jpeg_quality:Number(d.jpeg_quality),perceptual_hash_distance:Number(d.perceptual_hash_distance),perceptual_hash_enabled:Boolean(d.perceptual_hash_enabled)},ocr:{...(existing.ocr||{}),enabled:Boolean(d.enable_ocr),language:d.ocr_language||'chi_sim+eng',minimum_confidence:Number(d.ocr_minimum_confidence)},asr:{...(existing.asr||{}),enabled:Boolean(d.enable_asr),model_config_id:d.asr_model_config_id||null,language:d.asr_language||'zh',auto_detect_language:Boolean(d.auto_detect_language),vad:Boolean(d.vad),punctuation:Boolean(d.punctuation),maximum_segment_seconds:Number(d.maximum_segment_seconds),segment_overlap_seconds:Number(d.segment_overlap_seconds),speaker_diarization:Boolean(d.speaker_diarization),extract_audio_events:Boolean(d.extract_audio_events),generate_summary:Boolean(d.generate_summary),generate_chapters:Boolean(d.generate_chapters),minimum_speech_seconds:Number(d.minimum_speech_seconds),silence_policy:d.silence_policy},vision:{...(existing.vision||{}),enabled:Boolean(d.enable_vision),model_config_id:d.vision_model_config_id||null,execution:d.vision_execution,batch_size:Number(d.vision_batch_size),concurrency:Number(d.vision_concurrency),timeout_seconds:Number(d.vision_timeout_seconds),max_tokens:Number(d.vision_max_tokens),prompt_version:d.vision_prompt_version||'media-visible-facts-v1',generate_scene_summary:Boolean(d.generate_scene_summary),generate_video_summary:Boolean(d.generate_video_summary)},cache:{...(existing.cache||{}),enabled:true}};
  if(config.processing_mode==='local'&&config.vision.execution==='cloud')config.vision.enabled=false;
  return {name:d.name.trim(),description:d.description||'',applicable_media_types:types,config,enabled:Boolean(d.enabled),is_default:Boolean(d.is_default)};
}
async function editMediaPolicy(x){const ok=await modal(x?'编辑媒体解析策略':'新增媒体解析策略',mediaPolicyForm(x),async(d,form)=>api(x?`/media-policies/${x.id}`:'/media-policies',{method:x?'PUT':'POST',body:mediaPolicyPayload(d,form,x?.config||{})}),'保存',form=>{const mode=form.querySelector('[name=processing_mode]'),execution=form.querySelector('[name=vision_execution]'),vision=form.querySelector('[name=enable_vision]');const sync=()=>{const blocked=mode.value==='local'&&execution.value==='cloud';if(blocked)vision.checked=false;vision.disabled=blocked};mode.onchange=sync;execution.onchange=sync;sync()});if(ok){toast('媒体解析策略已保存');renderMediaPolicies()}}
async function viewMediaPolicyVersions(x){const rows=await api(`/media-policies/${x.id}/versions`);await modal(`${x.name} · 版本`,table(['版本','配置指纹','创建时间'],rows.map(row=>`<tr><td>V${row.version_number}</td><td class="mono">${esc(String(row.config_hash||'').slice(0,16))}</td><td>${fmtDate(row.created_at)}</td></tr>`)),async()=>{},'关闭')}
async function validateMediaPolicy(x){const out=await api(`/media-policies/${x.id}/validate`,{method:'POST'});const labels={asr:'语音识别',vision:'视觉理解',cloud_permission:'云端许可',frame_budget:'抽帧预算'};await modal(`${x.name} · 配置校验`,`<div class="media-validation-summary ${out.ok?'ok':'warning'}"><b>${out.ok?'配置可执行':'配置尚未就绪'}</b><span>策略 V${out.version}</span></div>${out.checks.map(item=>`<div class="media-validation-row"><span>${esc(labels[item.name]||item.name)}</span>${status(item.status)}<small>${esc(item.message||'')}</small></div>`).join('')}`,async()=>{},'关闭')}
async function renderMediaPolicies(){
  if(!state.user.is_admin)return go('dashboard');actions('<button id="media-policy-add">新增媒体策略</button>');const [rows,models]=await Promise.all([api('/media-policies'),api('/model-configs')]);state.mediaPolicies=rows;state.models=models;
  const frameLabel={smart:'智能抽帧',fixed_interval:'固定间隔',fixed_fps:'固定帧率',scene:'场景变化'};
  page('媒体解析策略',`<div class="media-policy-summary"><span>视频上传时可选择策略并预估抽帧数量；文档版本保存不可变策略快照。</span></div>${table(['名称','适用媒介','处理方式','抽帧','模型','版本','使用','状态','操作'],rows.map(x=>{const c=x.config||{},f=c.frame||{},modelsUsed=[c.asr?.model_config_id?'ASR':'',c.vision?.model_config_id?'视觉':''].filter(Boolean).join(' + ')||'仅基础解析';return `<tr><td><b>${esc(x.name)}</b>${x.is_default?'<small class="table-note">默认策略</small>':''}</td><td>${esc((x.applicable_media_types||[]).map(v=>({image:'图片',audio:'音频',video:'视频'}[v]||v)).join('、'))}</td><td>${esc(({local:'仅本地',cloud:'云端',hybrid:'混合'}[c.processing_mode]||c.processing_mode))}</td><td>${esc(frameLabel[f.mode]||f.mode||'—')}<small class="table-note">上限 ${f.max_frames??'—'} 帧</small></td><td>${esc(modelsUsed)}</td><td>V${x.current_version}</td><td>${x.usage?.spaces||0} 空间 · ${x.usage?.sources||0} 数据源</td><td>${status(x.enabled?'available':'disabled')}</td><td class="actions">${btn('校验','media-validate',x.id)}${btn('版本','media-versions',x.id)}${btn('复制','media-clone',x.id)}${btn('编辑','media-edit',x.id)}${btn('删除','media-delete',x.id,'danger')}</td></tr>`}))}`);
  $('#media-policy-add').onclick=()=>editMediaPolicy();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(row=>row.id===b.dataset.id);try{if(b.dataset.action==='media-edit')editMediaPolicy(x);if(b.dataset.action==='media-validate')validateMediaPolicy(x);if(b.dataset.action==='media-versions')viewMediaPolicyVersions(x);if(b.dataset.action==='media-clone'){await api(`/media-policies/${x.id}/clone`,{method:'POST'});toast('策略已复制');renderMediaPolicies()}if(b.dataset.action==='media-delete'&&confirm(`删除媒体策略“${x.name}”？`)){await api(`/media-policies/${x.id}`,{method:'DELETE'});toast('策略已删除');renderMediaPolicies()}}catch(err){toast(err.message,true)}};
}

async function renderOrgs(){
  actions('<button id="org-add">新增组织</button>');const rows=await api('/org-units');state.orgs=rows;const names=Object.fromEntries(rows.map(x=>[x.id,x.name]));
  page('组织机构',table(['编码','名称','上级','类型','顺序','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(names[x.parent_id]||'—')}</td><td>${esc(x.unit_type)}</td><td>${x.sort_order}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('编辑','org-edit',x.id)}${btn('删除','org-delete',x.id,'danger')}</td></tr>`)));
  $('#org-add').onclick=()=>editOrg();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);if(b.dataset.action==='org-edit')editOrg(x);if(b.dataset.action==='org-delete'&&confirm(`删除 ${x.name}？`)){try{await api(`/org-units/${x.id}`,{method:'DELETE'});renderOrgs()}catch(err){toast(err.message,true)}}};
}
function orgForm(x={}){return `<div class="field-row">${field('code','编码',x.code,'text','required')}${field('name','名称',x.name,'text','required')}</div>`+`<div class="field-row">${selectField('parent_id','上级组织',opt(state.orgs.filter(o=>o.id!==x.id),'无'),x.parent_id||'')}${selectField('unit_type','类型',[['group','集团'],['company','子企业'],['department','部门'],['team','团队']],x.unit_type||'department')}</div>`+field('sort_order','排序',x.sort_order||0,'number')+check('enabled','启用',x.enabled??true)}
async function editOrg(x){const ok=await modal(x?'编辑组织':'新增组织',orgForm(x),async d=>{d.sort_order=Number(d.sort_order);if(!d.parent_id)d.parent_id=null;await api(x?`/org-units/${x.id}`:'/org-units',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderOrgs()}}

async function renderRoles(){
  actions('<button id="role-add">新增角色</button>');const rows=await api('/roles');state.roles=rows;
  page('角色',table(['编码','名称','权限','内置','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.code)}</td><td>${esc(x.name)}</td><td class="truncate">${esc((x.permissions||[]).join(', '))}</td><td>${x.builtin?'是':'—'}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('编辑','role-edit',x.id)}${!x.builtin?btn('删除','role-delete',x.id,'danger'):''}</td></tr>`)));
  $('#role-add').onclick=()=>editRole();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);if(b.dataset.action==='role-edit')editRole(x);if(b.dataset.action==='role-delete'&&confirm(`删除 ${x.name}？`)){await api(`/roles/${x.id}`,{method:'DELETE'});renderRoles()}};
}
function roleForm(x={}){return `<div class="field-row">${field('code','编码',x.code,'text',x.id?'disabled':'required')}${field('name','名称',x.name,'text','required')}</div>`+`<label class="field"><span>权限（逗号分隔）</span><textarea name="permissions__list">${esc((x.permissions||[]).join(', '))}</textarea></label>`+check('enabled','启用',x.enabled??true)}
async function editRole(x){const ok=await modal(x?'编辑角色':'新增角色',roleForm(x),async d=>{if(x)delete d.code;await api(x?`/roles/${x.id}`:'/roles',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderRoles()}}

async function renderUsers(){
  actions('<button id="user-add">新增用户</button>');await refreshLookups();const rows=state.users;const orgNames=Object.fromEntries(state.orgs.map(x=>[x.id,x.name]));
  page('用户',table(['账号','姓名','组织','管理员','角色','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.username)}</td><td>${esc(x.display_name)}</td><td>${esc(orgNames[x.org_unit_id]||'—')}</td><td>${x.is_admin?'是':'—'}</td><td>${esc((x.role_ids||[]).map(id=>state.roles.find(r=>r.id===id)?.name||id).join(', '))}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('编辑','user-edit',x.id)}${btn('重置密码','user-pass',x.id)}${x.id!==state.user.id?btn('删除','user-delete',x.id,'danger'):''}</td></tr>`)));
  $('#user-add').onclick=()=>editUser();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);if(b.dataset.action==='user-edit')editUser(x);if(b.dataset.action==='user-pass')resetPassword(x);if(b.dataset.action==='user-delete'&&confirm(`删除 ${x.display_name}？`)){await api(`/users/${x.id}`,{method:'DELETE'});renderUsers()}};
}
function roleChecks(selected=[]){return `<label class="field"><span>角色</span><div>${state.roles.map(r=>`<label class="check"><input type="checkbox" name="role_pick" value="${r.id}" ${selected.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div></label>`}
function userForm(x={}){return `<div class="field-row">${field('username','账号',x.username,'text',x.id?'disabled':'required')}${field('display_name','姓名',x.display_name,'text','required')}</div>`+(!x.id?field('password','初始密码','','password','required minlength="10"'):'')+`<div class="field-row">${field('email','邮箱',x.email||'','email')}${selectField('org_unit_id','所属组织',opt(state.orgs),x.org_unit_id||'')}</div>`+roleChecks(x.role_ids||[])+`<div class="field-row">${check('is_admin','平台管理员',x.is_admin||false)}${check('enabled','启用',x.enabled??true)}</div>`}
async function editUser(x){const ok=await modal(x?'编辑用户':'新增用户',userForm(x),async(d,form)=>{d.role_ids=[...form.querySelectorAll('[name=role_pick]:checked')].map(i=>i.value);delete d.role_pick;if(x)delete d.username;await api(x?`/users/${x.id}`:'/users',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderUsers()}}
async function resetPassword(x){const ok=await modal('重置密码',field('new_password','新密码','','password','required minlength="10"'),async d=>api(`/users/${x.id}/password`,{method:'PUT',body:d}));if(ok)toast('密码已重置')}

async function renderSpaces(){
  actions(state.user.is_admin?'<button id="space-add">新增空间</button>':'');await refreshLookups();const rows=state.spaces;
  page('知识空间',table(['编码','名称','描述','负责人','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.code)}</td><td>${esc(x.name)}</td><td class="truncate">${esc(x.description)}</td><td>${esc(state.users.find(u=>u.id===x.owner_id)?.display_name||'—')}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('权限','space-grants',x.id)}${btn('编辑','space-edit',x.id)}${btn('删除','space-delete',x.id,'danger')}</td></tr>`)));
  if(state.user.is_admin)$('#space-add').onclick=()=>editSpace();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);if(b.dataset.action==='space-edit')editSpace(x);if(b.dataset.action==='space-grants')manageGrants(x);if(b.dataset.action==='space-delete'&&confirm(`删除 ${x.name}？`)){try{await api(`/spaces/${x.id}`,{method:'DELETE'});renderSpaces()}catch(err){toast(err.message,true)}}};
}
function spaceForm(x={}){return `<div class="field-row">${field('code','编码',x.code,'text','required')}${field('name','名称',x.name,'text','required')}</div>`+area('description','描述',x.description||'')+`<div class="field-row">${selectField('owner_id','负责人',opt(state.users),x.owner_id||'')}${selectField('media_policy_id','默认媒体策略',opt(state.mediaPolicies,'平台默认策略'),x.media_policy_id||'')}</div>`+check('enabled','启用',x.enabled??true)}
async function editSpace(x){const ok=await modal(x?'编辑空间':'新增空间',spaceForm(x),async d=>{if(!d.owner_id)d.owner_id=null;if(!d.media_policy_id)d.media_policy_id=null;await api(x?`/spaces/${x.id}`:'/spaces',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderSpaces()}}
async function manageGrants(space){
  const grants=await api(`/spaces/${space.id}/grants`);const subjects={user:state.users,role:state.roles,org:state.orgs};const name=g=>subjects[g.subject_type]?.find(x=>x.id===g.subject_id)?.name||subjects[g.subject_type]?.find(x=>x.id===g.subject_id)?.display_name||g.subject_id;
  const typeOptions=[['org','组织'],['role','角色'],['user','用户']],subjectOptions=type=>subjects[type].map(x=>[x.id,x.display_name||x.name||x.username]);
  const body=`<div class="field-row">${selectField('subject_type','对象类型',typeOptions,'org')}${selectField('subject_id','对象',subjectOptions('org'),'','required')}</div><div class="field-row">${selectField('permission','权限',[['read','读取'],['write','编辑'],['manage','管理']],'read')}</div>`+table(['对象','类型','权限','效果','操作'],grants.map(g=>`<tr data-grant="${g.id}"><td>${esc(name(g))}</td><td>${esc(g.subject_type)}</td><td>${esc(g.permission)}</td><td>${esc(g.effect)}</td><td>${btn('删除','grant-delete',g.id,'danger')}</td></tr>`));
  const added=await modal(`${space.name} · 权限`,body,async d=>{if(!d.subject_id)throw new Error('当前对象类型下没有可授权对象');await api(`/spaces/${space.id}/grants`,{method:'POST',body:{subject_type:d.subject_type,subject_id:d.subject_id,permission:d.permission,effect:'allow'}})},'添加',form=>{
    const type=form.querySelector('[name=subject_type]'),subject=form.querySelector('[name=subject_id]');
    type.onchange=()=>{subject.innerHTML=subjectOptions(type.value).map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('')};
    form.querySelectorAll('[data-action=grant-delete]').forEach(button=>button.onclick=async e=>{e.preventDefault();try{await api(`/spaces/${space.id}/grants/${button.dataset.id}`,{method:'DELETE'});button.closest('tr')?.remove();toast('权限已删除')}catch(err){toast(err.message,true)}});
  });
  if(added){toast('权限已添加');manageGrants(space)}
}

async function renderDocuments(){
  if(state.jobsTimer){clearTimeout(state.jobsTimer);state.jobsTimer=null}state.documentsMode='list';
  actions('<button class="secondary" id="doc-jobs">任务</button><button id="doc-upload">上传文档</button>');await refreshLookups();const rows=await api('/documents');const names=Object.fromEntries(state.spaces.map(x=>[x.id,x.name]));
  page('文档',table(['标题','空间','状态','标签','更新时间','操作'],rows.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(names[x.space_id]||x.space_id)}</td><td>${status(x.status)}</td><td>${esc((x.tags||[]).join(', '))}</td><td>${fmtDate(x.updated_at)}</td><td class="actions">${btn('查看','doc-view',x.id)}${btn('加工','doc-process',x.id)}${btn('编辑','doc-edit',x.id)}${btn('上传新版本','doc-version',x.id)}${btn('删除','doc-delete',x.id,'danger')}</td></tr>`)));
  $('#doc-jobs').onclick=()=>go('jobs');$('#doc-upload').onclick=()=>uploadDoc();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(r=>r.id===b.dataset.id);try{if(b.dataset.action==='doc-view')viewDoc(x);if(b.dataset.action==='doc-process'){b.disabled=true;await api(`/documents/${x.id}/process`,{method:'POST'});toast('知识加工任务已提交');go('jobs')}if(b.dataset.action==='doc-edit')editDoc(x);if(b.dataset.action==='doc-version')uploadDoc(x);if(b.dataset.action==='doc-delete'&&confirm(`删除 ${x.title} 及所有版本？`)){await api(`/documents/${x.id}`,{method:'DELETE'});renderDocuments()}}catch(err){b.disabled=false;toast(err.message,true)}};
}
