    const probe=async()=>{const file=input.files[0],type=mediaType(file);form.dataset.mediaType=type;section.classList.toggle('hidden',!type);videoOptions.classList.toggle('hidden',type!=='video');if(!type){form.dataset.highFrameEstimate='false';return}const sequence=++probeSequence;probeResult.textContent='正在检测媒体信息…';const d=formData(form),fd=new FormData();fd.set('file',file);if(d.media_policy_id)fd.set('media_policy_id',d.media_policy_id);if(d.upload_use_custom)fd.set('media_policy_override',JSON.stringify(uploadMediaOverride(d)));try{const out=await api('/media/probe',{method:'POST',body:fd});if(sequence!==probeSequence)return;const p=out.probe||{},estimate=out.frame_estimate,cloud=out.policy?.uses_cloud_vision,confirmNeeded=cloud&&out.policy?.cloud_confirmation_mode==='per_upload';cloudConfirm.classList.toggle('hidden',!confirmNeeded);const tooMany=Boolean(estimate&&(estimate.limited||estimate.estimated_frames>100));form.dataset.highFrameEstimate=String(tooMany);frameBudgetConfirm.classList.toggle('hidden',!tooMany);if(!tooMany)frameBudgetConfirm.querySelector('input').checked=false;const suggestion=tooMany&&p.duration_seconds?Math.max(1,Math.ceil(p.duration_seconds/100)):null;probeResult.innerHTML=`<b>${esc(type==='video'?'视频':'音频/图片')}检测完成</b><span>${p.duration_seconds?`时长 ${Math.round(p.duration_seconds*10)/10} 秒 · `:''}${p.width&&p.height?`${p.width}×${p.height} · `:''}${estimate?`预计 ${estimate.estimated_frames} 帧${estimate.limited?'（达到硬上限）':''}`:'将按策略处理'} · ${cloud?'将发送关键帧到云端':'不发送云端'}</span>${tooMany?`<small class="warning-text">关键帧较多，建议间隔不小于 ${suggestion} 秒；也可确认按当前设置继续。</small>`:''}`}catch(err){form.dataset.highFrameEstimate='false';frameBudgetConfirm.classList.add('hidden');if(sequence===probeSequence)probeResult.innerHTML=`<span class="error-inline">${esc(err.message)}</span>`}};
    input.onchange=probe;custom.onchange=()=>{syncCustom();probe()};savePolicy?.addEventListener('change',syncCustom);form.querySelector('[name=media_policy_id]').onchange=probe;form.querySelectorAll('#video-frame-options input,#video-frame-options select,.media-upload-core input').forEach(control=>control.onchange=probe);syncCustom();
