async function editDoc(x){const ok=await modal('编辑文档',field('title','标题',x.title,'text','required')+`<label class="field"><span>标签（逗号分隔）</span><input name="tags__list" value="${esc((x.tags||[]).join(', '))}"></label>`,async d=>api(`/documents/${x.id}`,{method:'PUT',body:d}));if(ok){toast('已保存');renderDocuments()}}
const MEDIA_STAGE_LABELS={queued:'等待处理',download:'读取媒体',probe:'检测媒体',media_probe:'检测媒体',preprocess:'预处理',asr:'语音转写',scene_detection:'场景检测',frame_extraction:'视频抽帧',ocr:'画面 OCR',vision:'视觉理解',cache_hit:'复用已验证结果',timeline_fusion:'生成媒体时间线',persistence:'保存结果',provenance:'生成溯源',completed:'已完成',failed:'处理失败',cancelled:'已取消',cancel_requested:'正在取消'};
