  const body=`<div class="form-section"><b>当前生效画像</b>${profileComparison(profile)}</div>`+area('summary','摘要',current.summary||'')+`<div class="field-row">${field('classification','主题分类',current.classification||'')}${field('document_type','文档类型',current.document_type||'')}</div>`+tokenField('tags','标签',current.tags||[])+tokenField('keywords','关键词',current.keywords||[])+tokenField('main_objects','主要对象',current.main_objects||[])+`<div class="field-row">${field('time_start','开始时间',asDate(time.start),'date')}${field('time_end','结束时间',asDate(time.end),'date')}</div>${timeHint}`+scopeOptions()+area('reason_note','调整说明','')+`<div class="impact-preview"><b>生效后将影响</b><span>文档画像</span><span>知识服务</span></div>`;
