  if(!standalone)$('#jobs-back').onclick=renderDocuments;$('#jobs-refresh').onclick=renderDocumentJobs;$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='job-view')viewJob(b.dataset.id);if(b.dataset.action==='job-retry'){await api(`/jobs/${b.dataset.id}/retry`,{method:'POST'});toast('已重新提交');renderDocumentJobs()}if(b.dataset.action==='job-delete'&&confirm('删除该任务记录？')){await api(`/jobs/${b.dataset.id}`,{method:'DELETE'});renderDocumentJobs()}}catch(err){toast(err.message,true)}};
