    if(d.left_entity_id===d.right_entity_id)throw new Error('请选择两个不同实体');if(d.operation==='merge'&&!d.winner_entity_id)d.winner_entity_id=d.left_entity_id;if(d.operation==='split')d.winner_entity_id=null;
